INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ttd_122', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-1-2' AND is_deleted = false LIMIT 1), 'course-progress-from-test-list', 'Calculate course progress from the test list', 'The CodeDev course page showed "NaN%" for a brand-new course and "125%" for a learner who double-clicked "Mark as complete". Before fixing calculateProgress(lessons, completions), the team wrote its test list first. A lesson is { id, required } and a completion event is { lessonId }; both arrays come from JSON, so the parameters are typed unknown. Make every item of the list true:

1. Happy path: percent = completed required lessons * 100 / required lessons, rounded down to a whole number (2 of 3 is 66; 100 only when every required lesson is done).
2. Optional lessons (required: false) count neither as done nor in the total.
3. A completion for a lesson that is not in the course is ignored, not an error.
4. Repeated requests: the same lesson completed several times counts once.
5. A course with no required lessons (no lessons at all, or only optional ones) gives percent 0, not NaN.
6. Invalid input gives { ok: false, error: "invalid_input" }: lessons or completions is not an array; a lesson is not an object, its id is not a positive integer (1, 2, 3 ...) or its required is not a boolean; a completion is not an object or its lessonId is not a positive integer. Validate everything before counting: an invalid completion is an error even when its lesson is not in the course.

A valid result is { ok: true, percent, completedRequired, totalRequired }. The test runner reads a list of cases { lessons, completions } as JSON and prints one result per case.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
