const COUPONS: Record<string, Coupon> = loadCoupons();

export function applyCoupon(cart: Cart, code: string): Cart {
  const coupon = COUPONS[code];
  if (coupon.expiresAt < cart.now) throw new Error("coupon expired");
  return { ...cart, total: cart.total - coupon.discount };
}

// coupons.test.ts
it("rejects an expired coupon", () => {
  expect(() => applyCoupon(cart, "SUMMER24")).toThrow();
});

$ npx vitest run coupons
 ✓ coupons.test.ts > rejects an expired coupon

The coupon list was reloaded last week and "SUMMER24" is no longer in COUPONS.

Statement: "This green test shows that applyCoupon still rejects expired coupons."', 'single_choice'::question_type, 'False. With SUMMER24 gone, COUPONS[code] is undefined at runtime (the Record type promises a coupon for every string key, so tsc does not object), and coupon.expiresAt throws TypeError: Cannot read properties of undefined (reading ''expiresAt''). toThrow() with no argument accepts any error, so the crash counts as a pass. The test no longer reaches the expiry check at all. Write toThrow("coupon expired") and the test fails with a message that shows the TypeError, which also reveals that an unknown coupon code crashes instead of being refused. The misconception is that "it threw" means "it threw for the reason in the test name".', 1, 5
