VALUES ('chal_coding_ttd_212', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-2-1' AND is_deleted = false LIMIT 1), 'submission-deadline-with-clock', 'A deadline function that takes a clock', 'CodeDev decides whether a learner may still submit an assignment. The shipped submissionStatus read new Date() inside, so its test built "today" from the real clock and failed every night between 00:00 and 07:00 Vietnam time. Write submissionStatus(assignment, clock) so that it reads the current time only from clock.now() (never new Date() or Date.now()). assignment.deadline is a wall-clock time "YYYY-MM-DDTHH:mm" in the learner''s fixed UTC offset assignment.utcOffsetMinutes (420 = UTC+7, 0 = UTC, -300 = UTC-5, an integer between -720 and 840); the deadline instant is that wall time at second 0 in that offset, so "2026-10-31T23:59" at 420 is 2026-10-31T16:59:00.000Z. Return "on-time" when now <= deadline, "late" when deadline < now <= deadline + graceMinutes, "closed" when now is later than that, and "invalid" when the deadline does not match YYYY-MM-DDTHH:mm exactly, is not a real date and time (2026-02-29T10:00, 2026-10-31T24:00, minute 60, month 13), or graceMinutes is not a whole number >= 0. Input (read by the runner): a JSON list of { assignment: { id, deadline, utcOffsetMinutes, graceMinutes }, at: [ISO instants] }. For every instant the runner builds a clock fixed at it and prints "<id> at <instant>: <status>", one line per instant.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
