-- challenge chal_quiz_ttd_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ttd_221', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-2-2' AND is_deleted = false LIMIT 1), 'fakes-stubs-mocks-quiz', 'Would this test notice the bug?', 'Two EnrollmentService tests from the double-click incident: one built from vi.fn() mocks, one built on an in-memory fake that returns the objects it stores.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_221'), 'EnrollmentService.enroll() calls repo.create() inside try { ... } catch, and maps DuplicateEnrollmentError to { ok: false, error: "already_enrolled" }. Its test (Vitest 3.x):

const repo = {
  create: vi.fn().mockResolvedValue({ id: "e1", userId: "u1", courseId: "ts-101", status: "active", progress: 0, enrolledAt: "2026-10-26T08:14:03.000Z" }),
  findById: vi.fn(), findByUser: vi.fn(), update: vi.fn(), delete: vi.fn(),
};
const service = new EnrollmentService(repo, clock);
const first = await service.enroll("u1", "ts-101");
await service.enroll("u1", "ts-101");
expect(first.ok).toBe(true);
expect(repo.create).toHaveBeenCalledTimes(2);

Statement: "If someone deletes the catch block from enroll(), this test fails."', 'single_choice'::question_type, 'False. mockResolvedValue makes create() succeed on every call, so the second enroll() never throws and the catch block never runs in this test. Delete it and both assertions still hold: first.ok is true and create was called twice. The test checks the wiring (a call happened) and an assumption written by the test author (create always succeeds), not the behaviour learners depend on (a double click returns already_enrolled). The misconception is that a test that mentions the double click covers it. With a fake that refuses a second (userId, courseId), the second enroll() reaches the catch block, and an assertion on its result fails when the block is removed.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_221') AND order_index = 1)
    RETURNING id
)
