-- challenge chal_coding_ttd_222 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ttd_222', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-2-2' AND is_deleted = false LIMIT 1), 'fake-enrollment-repository', 'An in-memory fake that keeps the repository contract', 'The EnrollmentService tests needed PostgreSQL and took nine minutes, and the vi.fn() mocks that replaced it hid a 500 on double clicks. Write FakeEnrollmentRepository, an in-memory class that implements the given EnrollmentRepository interface with the same contract as the real PostgreSQL repository, so the unchanged EnrollmentService can be tested against it. Contract: create(input) stores a copy with a new id "e1", "e2", ... from a counter that is never reused (not even after a delete) and returns a copy; a second row with the same (userId, courseId), whatever its status, is refused with throw new DuplicateEnrollmentError(userId, courseId), like the unique constraint enrollments_user_course_key. findById(id) returns a copy or null. findByUser(userId) returns copies of that user''s rows ordered by enrolledAt, oldest first, rows with the same enrolledAt in creation order, or []. update(id, changes) applies status and/or progress (an empty object changes nothing) and returns a copy of the updated row, or null for an unknown id. delete(id) is idempotent: true when a row was removed, false when there was none, never an exception. A caller that changes a returned object, or the object it passed to create, must not change the stored row. The interface is synchronous here to keep the runner small (the real one returns Promises). Input (read by the runner): a JSON list of steps run against one service that uses your fake - enroll (with the instant the stub clock returns), progress, cancel, leave, dashboard, and tamper (a caller changes every object the repository returned, then reads the row again). Output: one line per step, as printed by the runner.', 'open', 'easy'::difficulty_question, 'mini_coding', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
