INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_222'), 1, 'PostgreSQL hands every caller a new object built from the row. What do you have to do at each point where a row enters or leaves your repository so that the fake behaves the same way?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_222'), 2, 'Look at what the service does with each result: enroll() relies on an exception of one exact class (instanceof), dashboard() relies on the order of findByUser(), and the runner''s enroll and tamper steps change the objects they receive. A Map keeps insertion order, and Array.prototype.sort is stable.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_222'), 3, 'A similar fake for a different contract, a store of certificates: issue(userId, courseId) { const key = userId + "|" + courseId; if (this.certs.has(key)) throw new AlreadyIssuedError(key); const cert = { code: "C" + this.next++, userId, courseId }; this.certs.set(key, cert); return { ...cert }; } - the key enforces uniqueness, the counter never goes back, and the caller gets a copy.');
