Evidence D - the enrolment code and its test:
// src/enrollment/enrollment.ts
export async function enrollInTrial(db: Db, userId: string, courseId: string) {
  const startedAt = Math.floor(Date.now() / 1000) * 1000;   // stored in whole seconds
  const trialEndsAt = new Date(startedAt + 7 * DAY_MS).toISOString();
  await db.enrollments.insert({ userId, courseId, trialEndsAt });
  return { userId, courseId, trialEndsAt };
}

// src/enrollment/enrollment.test.ts
test("trial ends 7 days after enrolment", async () => {
  const expected = new Date(Math.floor(Date.now() / 1000) * 1000 + 7 * DAY_MS).toISOString();
  const course = await createCourse(db, { slug: "typescript-test-design" }); // about 150 ms on CI
  const enrollment = await enrollInTrial(db, "u_8812", course.id);
  expect(enrollment.trialEndsAt).toBe(expected);
});

Statement: "The expiry failure happens in runs where the clock passes a whole second between the test''s Date.now() and the Date.now() inside enrollInTrial; with about 150 ms of setup between the two calls, that happens in some runs and not in others."', 'single_choice'::question_type, 'True. The test computes its expected value first, then spends about 150 ms creating a course, then calls enrollInTrial, which reads the clock again. Both round down to the whole second. If both reads fall in the same second (07:09:40.2 and 07:09:40.35) the values match; if the second ticks over in between (07:09:40.9 and 07:09:41.05) the code rounds to 07:09:41 and the test expected 07:09:40 - exactly one second, as in log B. With 150 ms between the reads, roughly one run in seven crosses a second, which fits 6 failures in 50 runs. The misconception is that two Date.now() calls in one test see the same time; the fix is to give the code a clock the test controls.', 2, 5
