Evidence D - the leaderboard code, its tests and the Vitest config:
// vitest.config.ts
export default defineConfig({ test: { isolate: false } }); // PR #577: share modules between test files, CI 40% faster

// src/leaderboard/leaderboard.ts
const totals = new Map<string, number>();   // one map for the whole module
export const setPoints = (user: string, points: number) => { totals.set(user, points); };
export const addPoints = (user: string, points: number) => { totals.set(user, (totals.get(user) ?? 0) + points); };
export const pointsOf = (user: string) => totals.get(user) ?? 0;
export const ranking = () =>
  [...totals].sort((a, b) => b[1] - a[1]).map(([user, points]) => `${user} ${points}`);

// src/leaderboard/leaderboard.test.ts
test("ranks learners by points, ties by name", () => {
  setPoints("an", 120);
  setPoints("binh", 120);
  setPoints("chi", 80);
  expect(ranking()).toEqual(["an 120", "binh 120", "chi 80"]);
});

// src/leaderboard/streak.test.ts
test("a 7-day streak adds 20 bonus points", () => {
  setPoints("binh", 100);
  addPoints("binh", streakBonus(7));
  expect(pointsOf("binh")).toBe(120);
});

Statement: "The leaderboard failure does not depend on other test files: running leaderboard.test.ts on its own would fail the same way about one run in five."', 'single_choice'::question_type, 'False. On its own, the test starts with an empty map and inserts an, binh, chi in that order. The comparator only compares points, and Array.prototype.sort is stable, so the tie between an and binh keeps insertion order and the test passes every time. It fails only when streak.test.ts ran earlier in the same worker: with isolate: false the module, and its map, is shared between files, so binh is already in the map and setPoints("binh", 120) keeps binh''s earlier position. Which files share a worker, and in which order, changes between CI runs. Two lessons hide here: shared module state makes the result depend on order, and the code never implemented "ties by name" at all - the test passed by luck of insertion order. The misconception is that a test which passes alone is correct.', 3, 5
