VALUES ('chal_coding_ttd_312', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-3-1' AND is_deleted = false LIMIT 1), 'fix-the-flaky-pipeline', 'Fix the Flaky Pipeline', 'The CodeDev trial week module keeps a small leaderboard for learners on a 7-day trial and tells them when the trial ends. Its tests go red about one CI run in five: sometimes the trial end is wrong, sometimes the ranking comes back in a different order, and a re-run of the same code is green. Locally, one test at a time, everything passes. Fix startCohort(now) so that every cohort gives the same answer for the same start time and awards, whatever order the awards arrive in and whatever ran before: trialEndsAt() is 7 days after the moment the cohort started (the time the injected clock now() returned when startCohort ran), rounded down to the whole second, as an ISO string; ranking() lists every learner with points as "name points", most points first, ties in alphabetical order of name; and every cohort starts empty. Awards whose points are not a positive whole number are ignored (that part already works). Input (read by the test runner, do not change it): { runs, seed, starts, awards }. Run i starts a cohort with a clock fixed at starts[i % starts.length] and gives it the awards in an order shuffled by a seeded random generator, so the shuffles are the same on every submission. Output: the number of runs and the seed, then every different ranking and, per start time, every different trial end, each with the number of runs that gave it. A correct module prints exactly one ranking line and one trial line per start time.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
