-- challenge chal_quiz_ttd_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ttd_321', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-3-2' AND is_deleted = false LIMIT 1), 'certificate-boundary-quiz', 'Which tests can see the 80% boundary?', 'Two pieces of evidence from the certificate service: the tests an AI assistant wrote for its own code, and a reviewer''s half fix that keeps the rounding.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321'), 'The AI-written function and the tests it wrote for it:

function isEligibleForCertificate(completed: number, required: number): boolean {
  if (required === 0) return true;
  const percent = Math.round((completed / required) * 100);
  return percent > 80;
}

test("certificate rules", () => {
  expect(isEligibleForCertificate(9, 10)).toBe(true);    // 90%
  expect(isEligibleForCertificate(1, 2)).toBe(false);    // 50%
  expect(isEligibleForCertificate(10, 10)).toBe(true);   // 100%
});

Statement: "These three tests would pass just the same if the comparison were percent >= 80, so they cannot tell the buggy version from the one the request asked for."', 'single_choice'::question_type, 'True. 90 and 100 are above 80 with either operator, and 50 is below it with either operator, so no assertion sits on the boundary where > and >= disagree. A test can only catch a boundary bug if one of its inputs is exactly on the boundary (4 of 5, 8 of 10) or right next to it on both sides (79.x% and 80.x%). The same tests also say nothing about required = 0 or invalid input. The misconception is that passing tests plus 100% line coverage means the rule is checked: every line ran, but no input could tell the two operators apart.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321'), 'A reviewer''s quick fix of the same function:

-  return percent > 80;
+  return percent >= 80;

Support then checks a few learners (percent before rounding in brackets):
  4 of 5    (80.00%)  -> eligible
  33 of 41  (80.49%)  -> eligible
  39 of 49  (79.59%)  -> eligible

Statement: "With >= 80 the rounding can only help learners who already reached 80%, so no learner below 80% gets a certificate any more."', 'single_choice'::question_type, 'False. Math.round turns every percentage from 79.5 up to 80.49... into 80, and 80 >= 80 is true, so 39 of 49 (79.59%) now gets a certificate: the rounding moved the boundary half a percent down. The fix is to compare without rounding, best in whole numbers: completed * 100 >= required * 80 (or completed * 5 >= required * 4). The half fix also keeps the other bug: a course with required = 0 still certifies everyone. The misconception is that rounding a value for display is harmless in a comparison; round only what you show, never what you decide on.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_321') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_ttd_322 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_ttd_322', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-3-2' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-certificate-boundary', 'Spot the AI Mistake: the 80% certificate boundary', 'An AI assistant was asked: "Write isEligibleForCertificate(completed, required) for the CodeDev certificate service. A learner gets the course certificate when they have completed at least 80% of the required items (lessons and graded challenges). Return true or false." Its function and its own three tests (9 of 10, 1 of 2, 10 of 10) pass, and the pull request was merged. Since then support has tickets from learners who finished exactly 4 of 5 items, or 33 of 41 (80.5%), and get no certificate, and a course whose required items were removed by mistake certifies everyone who opens it. Fix isEligibleForCertificate so that it follows the request: eligible when completed is at least 80% of required (exactly 80% counts); no certificate when required is 0; no certificate for invalid input (completed or required not a whole number, completed below 0, or completed greater than required). Input (read by the test runner, do not change it): a JSON list of [completed, required] pairs. Output: for up to 20 pairs, one line per pair, "<completed> of <required>: eligible" or "... not eligible"; for more pairs, one line "<n> pairs: <e> eligible, <m> not eligible". The public tests pass on the AI''s code; the hidden tests check the boundary, rounding traps, empty courses, invalid input and every pair up to 100 required items.', 'open', 'easy'::difficulty_question, 'fix_bug', 20, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322'), 1, 'Which inputs sit exactly on the boundary or just next to it, and what does the AI''s code answer for them? Try 4 of 5, then 39 of 49 (79.59%).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322'), 2, 'Look at the two lines that compute and compare the percent: what does Math.round do to 80.49 and to 79.59, and which operator decides what happens at exactly 80? Then read the first line again with the request in mind: does a course with nothing to complete meet "at least 80%"?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322'), 3, 'A similar rule: "pass with at least 2 of every 3 answers right". Instead of Math.round((right / total) * 100) > 66, compare whole numbers: right * 3 >= total * 2. 2 of 3 passes, 66 of 100 fails, 67 of 100 passes, and no rounding can move the line. Check the inputs with Number.isInteger before you compare.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322');
