       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_ttd_322'), 'Rounding traps: 80.49% is eligible, 79.5-79.8% is not', '[[33,41],[39,49],[35,44],[79,99],[47,59]]', '"33 of 41: eligible\n39 of 49: not eligible\n35 of 44: not eligible\n79 of 99: not eligible\n47 of 59: not eligible"', 2, false, true, 4),
