-- challenge chal_quiz_ttd_331 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_ttd_331', (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'typescript-test-design') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-ttd-3-3' AND is_deleted = false LIMIT 1), 'tests-that-catch-bugs-quiz', 'Would these tests notice?', 'Two pieces of evidence about the tests of the CodeDev coupon rule: a test file with full coverage, and one mutant that survived it.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_331');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_331');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_331'), '// src/checkout/coupon.ts
export function applyCoupon(price: number, coupon: Coupon, today: string): number {
  if (today > coupon.expiresOn) return price;
  if (price <= MIN_PRICE) return price;                     // MIN_PRICE = 10_000
  const discount = coupon.kind === "percent" ? Math.floor((price * coupon.value) / 100) : coupon.value;
  return Math.max(price - discount, MIN_PRICE);
}

// src/checkout/coupon.test.ts
const c = (kind: "percent" | "fixed", value: number, expiresOn = "2026-12-31") => ({ kind, value, expiresOn });
test("percent coupon", () => expect(applyCoupon(200000, c("percent", 10), "2026-10-26")).toBe(180000));
test("fixed coupon", () => expect(applyCoupon(199000, c("fixed", 20000), "2026-10-26")).toBe(179000));
test("expired coupon", () => expect(applyCoupon(199000, c("fixed", 20000, "2026-10-01"), "2026-10-26")).toBe(199000));
test("cheap course", () => expect(applyCoupon(5000, c("percent", 50), "2026-10-26")).toBe(5000));

Coverage report: coupon.ts  100% statements, 100% branches, 100% lines

Statement: "Because these four tests run every line and every branch of applyCoupon, at least one of them would fail if the last line were changed to return price - discount;"', 'single_choice'::question_type, 'False. Math.max(price - discount, MIN_PRICE) only matters when price - discount is below 10,000. In the tests it never is: 180,000 and 179,000 are far above it, the expired test returns before the line, and the cheap course returns on the line above. So without Math.max every test gives the same result and stays green, although a 50,000 VND coupon on a 49,000 VND course would now cost -1,000. Coverage records that the line ran; it says nothing about whether any assertion depends on what the line computes. To notice the change you need a case where the discount takes the price below the minimum. The misconception is that 100% line and branch coverage means every behaviour is checked.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_ttd_331') AND order_index = 1)
    RETURNING id
)
